declarations:
box-sizing: border-box;
  margin: 0;
  padding: 0;
  scrollbar-width: thin;
  scrollbar-color: rgba(148, 163, 184, 0.4) transparent;

background-color: rgba(148, 163, 184, 0.35);
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
  transition: background-color 0.2s ease;

--navy: #002847;
  --navy2: #001b30;
  --blue: #0878bd;
  --blue2: #05659f;
  --page: #f4f7fb;
  --card: #fff;
  --text: #15253b;
  --muted: #6b778b;
  --line: #dce3eb;
  --danger: #bd3f45;
  --success: #2f8c5a;
  --warning: #e0a01c;
  --shadow: 0 12px 32px rgba(16, 35, 58, .10);
  --motion-fast: 180ms;
  --motion-medium: 240ms;
  --motion-slow: 300ms;
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);

min-height: 100vh;
  --font-base: 'Inter', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-family: var(--font-base);
  color: var(--text);
  background: var(--page);

will-change: transform;
  transform: translateY(-2px);
  box-shadow: 0 8px 18px rgba(8, 120, 189, 0.12);

transform: translateY(-1px) scale(1.02);
  border-color: rgba(8, 120, 189, 0.3);
  box-shadow: 0 8px 20px rgba(8, 120, 189, 0.08);

transform: translateY(-4px);
  border-color: rgba(8, 120, 189, 0.32);
  box-shadow: 0 16px 32px rgba(20, 40, 60, 0.08), 0 0 0 1px rgba(115, 179, 230, 0.14);

content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, rgba(12, 128, 191, 0.12), rgba(118, 189, 248, 0.03), rgba(255, 255, 255, 0));
  opacity: 0;
  transition: opacity var(--motion-fast) var(--ease-out);
  pointer-events: none;

body:
0% {
    opacity: 0;
    transform: translate3d(0, 16px, 0);
    filter: blur(4px);
  }

  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0);
    filter: blur(0);
  }

*,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  .animate-in {
    opacity: 1;
    transform: none;
    filter: none;
  }

